                    <>
                        {/* Club Promo Balance Card */}
                        <div style={{
                            background: 'linear-gradient(135deg, #7c3aed 0%, #9333ea 100%)',
                            borderRadius: 12, padding: 20, marginBottom: 16,
                            border: '1px solid rgba(147,51,234,0.3)',
