            {/* ═══ PLAYER RETENTION MODAL ═══ */}
            {activeModal === 'retention' && (
                <div style={S.modalOverlay} onClick={() => setActiveModal(null)}>
                    <div style={S.modal} onClick={e => e.stopPropagation()}>
                        <div style={S.modalHeader}>
