                                                    </span>
                                                    <span style={{ color: (p.netResult || 0) >= 0 ? FB.success : FB.danger, fontWeight: 700 }}>
                                                        {(p.netResult || 0) >= 0 ? '+' : ''}{(p.netResult || 0).toLocaleString()}
                                                    </span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

